"""Вильоти VRChat — вікно з журналом.

Показує кожен вихід з інстансу: коли, чому (інтернет/роутер/VRChat),
що зробила служба auto_rejoin.py і скільки ти була поза світом.
Дані: ~/.local/state/vrchat-auto-rejoin/{events.jsonl,net.log,rejoin.log}.
"""
import json
import os
import sqlite3
import subprocess
import sys
import time
from collections import Counter
from pathlib import Path

from PySide6.QtCore import Qt, QTimer
from PySide6.QtGui import QColor, QFont
from PySide6.QtWidgets import (QApplication, QHBoxLayout, QHeaderView, QLabel,
                               QPlainTextEdit, QPushButton, QTableWidget,
                               QTableWidgetItem, QTabWidget, QVBoxLayout, QWidget)

STATE_DIR = Path.home() / ".local/state/vrchat-auto-rejoin"
VRCX_DB = Path.home() / ".config/VRCX/VRCX.sqlite3"
UK = os.environ.get("LANG", "").startswith("uk")


def L(uk, en):
    return uk if UK else en


GREEN, YELLOW, RED = "#4caf50", "#ffb300", "#f44336"
RESULTS = {
    "self":   (L("✔ VRChat повернувся сам", "✔ VRChat rejoined by itself"), GREEN),
    "same":   (L("✔ Повернула в той самий інстанс", "✔ Back in the same instance"), GREEN),
    "home":   (L("🏠 Відкрила дім «Друзі+»", "🏠 Opened home as Friends+"), YELLOW),
    "other":  (L("↪ Опинилась в іншому інстансі", "↪ Ended up in another instance"), YELLOW),
    "failed": (L("✖ Не вдалося повернути", "✖ Could not rejoin"), RED),
}


def plain_reason(reason):
    r = (reason or "").lower()
    if "перевищило час" in r or "timed out" in r or "timeout" in r:
        return L("Зʼєднання з VRChat обірвалось", "Connection to VRChat timed out")
    if "не відповідає" in r or "not responding" in r:
        return L("VRChat перестав відповідати", "VRChat stopped responding")
    if "network region" in r:
        return L("Не вдалося підʼєднатися до сервера", "Could not connect to the server")
    if "застрягла" in r or "stuck" in r:
        return L("Застрягла в меню", "Stuck in the menu")
    return reason or "?"


def plural(n, one, few, many):
    if n % 10 == 1 and n % 100 != 11:
        return one
    return few if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14 else many


def duration(sec):
    sec = int(sec)
    s, m, h = L("с", "s"), L("хв", "min"), L("год", "h")
    if sec < 60:
        return f"{sec} {s}"
    if sec < 3600:
        return f"{sec // 60} {m} {sec % 60} {s}"
    return f"{sec // 3600} {h} {sec % 3600 // 60} {m}"


def load_events():
    try:
        lines = (STATE_DIR / "events.jsonl").read_text().splitlines()
    except OSError:
        return []
    out = []
    for l in lines:
        try:
            out.append(json.loads(l))
        except ValueError:
            pass
    return sorted(out, key=lambda e: e["start"], reverse=True)


def load_outages():
    """net.log → список (початок, кінець, роутер_падав)."""
    try:
        lines = (STATE_DIR / "net.log").read_text().splitlines()
    except OSError:
        return []
    out, cur = [], None
    for l in lines:
        try:
            ts = time.mktime(time.strptime(l[:19], "%Y-%m-%d %H:%M:%S"))
        except ValueError:
            continue
        text = l[20:]
        # нові рядки починаються з мітки (OK/NO-…), старі — лише українські слова
        ok = text.startswith(("OK", "NO-PING")) or "все працює" in text or "інтернет є" in text
        if not ok:
            if cur is None:
                cur = [ts, None, False]
            cur[2] |= text.startswith("NO-ROUTER") or "РОУТЕР" in text
        elif cur is not None:
            cur[1] = ts
            out.append(tuple(cur))
            cur = None
    if cur is not None:
        out.append((cur[0], time.time(), cur[2]))
    return out


def cause(ev, outages):
    near = [o for o in outages if o[0] <= ev["start"] + 30 and o[1] >= ev["start"] - 240]
    if not near:
        return L("Інтернет був — збій на боці VRChat", "Internet was fine — VRChat-side problem")
    if any(o[2] for o in near):
        return L("Роутер перезавантажувався", "Router rebooted")
    return L("Зник інтернет (оператор/модем)", "Internet dropped (ISP/modem)")


def world_names():
    try:
        con = sqlite3.connect(f"file:{VRCX_DB}?mode=ro", uri=True, timeout=3)
        rows = con.execute("select world_id, world_name from gamelog_location group by world_id").fetchall()
        con.close()
        return dict(rows)
    except Exception:
        return {}


def cell(text, color=None, bold=False):
    it = QTableWidgetItem(text)
    it.setFlags(it.flags() & ~Qt.ItemIsEditable)
    if color:
        it.setForeground(QColor(color))
    if bold:
        f = it.font()
        f.setBold(True)
        it.setFont(f)
    return it


class Window(QWidget):
    def __init__(self):
        super().__init__()
        self.setWindowTitle(L("Вильоти VRChat", "VRChat kicks"))
        self.resize(1100, 600)
        f = self.font()
        f.setPointSize(f.pointSize() + 2)
        self.setFont(f)

        self.summary = QLabel()
        self.summary.setWordWrap(True)
        sf = QFont(self.font())
        sf.setPointSize(sf.pointSize() + 2)
        self.summary.setFont(sf)

        self.kicks = QTableWidget(0, 5)
        self.kicks.setHorizontalHeaderLabels([
            L("Коли", "When"), L("Що сталося", "What happened"), L("Чому", "Why"),
            L("Що зробила програма", "What the program did"), L("Поза світом", "Out of world")])
        self.net = QTableWidget(0, 3)
        self.net.setHorizontalHeaderLabels([L("Коли", "When"), L("Що зникло", "What was down"),
                                            L("Скільки", "How long")])
        for t in (self.kicks, self.net):
            t.verticalHeader().hide()
            t.setAlternatingRowColors(True)
            t.setSelectionBehavior(QTableWidget.SelectRows)
            t.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeToContents)
            t.horizontalHeader().setStretchLastSection(True)
        self.kicks.cellClicked.connect(self.show_detail)
        self.detail = QLabel(L("Натисни на рядок — тут буде видно світ і всі помилки.",
                               "Click a row to see the world and all errors here."))
        self.detail.setWordWrap(True)
        self.detail.setTextInteractionFlags(Qt.TextSelectableByMouse)

        self.raw = QPlainTextEdit()
        self.raw.setReadOnly(True)

        kicks_tab = QWidget()
        kl = QVBoxLayout(kicks_tab)
        kl.addWidget(self.kicks, 1)
        kl.addWidget(self.detail)

        tabs = QTabWidget()
        tabs.addTab(kicks_tab, L("Вильоти", "Kicks"))
        tabs.addTab(self.net, L("Інтернет", "Internet"))
        tabs.addTab(self.raw, L("Подробиці", "Details"))

        refresh = QPushButton(L("⟳ Оновити", "⟳ Refresh"))
        refresh.clicked.connect(self.reload)
        folder = QPushButton(L("📂 Папка з логами", "📂 Log folder"))
        folder.clicked.connect(lambda: subprocess.Popen(["xdg-open", str(STATE_DIR)]))
        buttons = QHBoxLayout()
        buttons.addStretch(1)
        buttons.addWidget(folder)
        buttons.addWidget(refresh)

        lay = QVBoxLayout(self)
        lay.addWidget(self.summary)
        lay.addWidget(tabs, 1)
        lay.addLayout(buttons)

        self.events = []
        self.reload()
        timer = QTimer(self)
        timer.timeout.connect(self.reload)
        timer.start(15000)

    def reload(self):
        self.events = load_events()
        outages = load_outages()
        names = world_names()

        week = [e for e in self.events if e["start"] > time.time() - 7 * 86400]
        back = sum(e.get("result") in ("self", "same") for e in week)
        # година, округлена до найближчої (04:57 → 05:00); кожен день рахуємо раз
        days = {(round(t.tm_hour + t.tm_min / 60) % 24, t.tm_yday)
                for t in (time.localtime(e["start"]) for e in self.events)}
        hours = Counter(h for h, _ in days)
        text = L(f"<b>За 7 днів:</b> вильотів — {len(week)}, повернуто в той самий інстанс — {back}",
                 f"<b>Last 7 days:</b> {len(week)} kicks, {back} back in the same instance")
        if hours:
            h, n = hours.most_common(1)[0]
            if n > 1:
                text += L(f"<br>Найчастіше близько <b>{h:02d}:00</b> — {n} "
                          f"{plural(n, 'день', 'дні', 'днів')} (зазвичай це обрив інтернету)",
                          f"<br>Most often around <b>{h:02d}:00</b> — on {n} days (usually an internet drop)")
        self.summary.setText(text)

        self.kicks.setRowCount(len(self.events))
        for i, e in enumerate(self.events):
            res, color = RESULTS.get(e.get("result"), (e.get("result", "?"), None))
            if e.get("result") == "same" and e.get("tries", 0) > 1:
                res += L(f" (спроб: {e['tries']})", f" ({e['tries']} tries)")
            e["_world"] = e.get("world") or names.get((e.get("instance") or "").split(":")[0], "")
            self.kicks.setItem(i, 0, cell(time.strftime("%d.%m %H:%M", time.localtime(e["start"])), bold=True))
            self.kicks.setItem(i, 1, cell(plain_reason(e.get("reason"))))
            self.kicks.setItem(i, 2, cell(cause(e, outages)))
            self.kicks.setItem(i, 3, cell(res, color))
            self.kicks.setItem(i, 4, cell(duration(e["end"] - e["start"]) if "end" in e else "…"))

        rows = sorted(outages, reverse=True)
        self.net.setRowCount(len(rows))
        for i, (a, b, router) in enumerate(rows):
            self.net.setItem(i, 0, cell(time.strftime("%d.%m %H:%M:%S", time.localtime(a)), bold=True))
            self.net.setItem(i, 1, cell(L("Роутер (перезавантаження)", "Router (reboot)") if router
                                        else L("Інтернет (оператор/модем)", "Internet (ISP/modem)"),
                                        RED if router else YELLOW))
            self.net.setItem(i, 2, cell(duration(b - a)))

        try:
            raw = (STATE_DIR / "rejoin.log").read_text(errors="replace").splitlines()
            self.raw.setPlainText("\n".join(reversed(raw[-400:])))
        except OSError:
            self.raw.setPlainText(L("Журналу ще немає.", "No log yet."))

    def show_detail(self, row, _col):
        e = self.events[row]
        parts = []
        if e.get("_world"):
            parts.append(f"<b>{L('Світ', 'World')}:</b> {e['_world']}")
        parts.append(f"<b>{L('Повідомлення VRChat', 'VRChat message')}:</b> {e.get('reason', '?')}")
        if e.get("tries"):
            parts.append(f"<b>{L('Перезапусків у той самий інстанс', 'Restarts into the same instance')}:</b> {e['tries']}")
        if e.get("home_tries"):
            parts.append(f"<b>{L('Спроб відкрити дім', 'Tries to open home')}:</b> {e['home_tries']}")
        if e.get("errors"):
            parts.append(f"<b>{L('Помилки', 'Errors')}:</b> " + "; ".join(dict.fromkeys(e["errors"])))
        if e.get("landed"):
            parts.append(f"<b>{L('Опинилась у', 'Ended up in')}:</b> {e['landed']}")
        self.detail.setText("<br>".join(parts))


if __name__ == "__main__":
    app = QApplication(sys.argv)
    app.setDesktopFileName("vrchat-kicks")
    w = Window()
    w.show()
    sys.exit(app.exec())
